"""Password checks for the login service."""
import bcrypt

USERS = {"alice": bcrypt.hashpw(b"wonderland", bcrypt.gensalt())}


def check_password(user: str, password: str) -> bool:
    expected = USERS.get(user)
    if expected is None:
        return False
    return bcrypt.checkpw(password.encode(), expected)
